using System;using System.Drawing;using System.Drawing.Drawing2D;using System.Globalization;using System.Linq;using System.Windows.Forms;
namespace BeamScheduleFormatter {
partial class WindDesignForm {
 WindBuildingModel buildingModel;readonly Timer buildingRefresh=new Timer{Interval=180};
 bool TryBuildingGeometry(out WindBuildingInput value){value=null;double w,l,e,a;if(!Inputs.ContainsKey("BuildingWidth")||!double.TryParse(Value("BuildingWidth"),NumberStyles.Float,CultureInfo.InvariantCulture,out w)||!double.TryParse(Value("BuildingLength"),NumberStyles.Float,CultureInfo.InvariantCulture,out l)||!double.TryParse(Value("Eave"),NumberStyles.Float,CultureInfo.InvariantCulture,out e)||!double.TryParse(Value("Apex"),NumberStyles.Float,CultureInfo.InvariantCulture,out a))return false;var b=new WindBuildingInput{Width=w,Length=l,Eave=e,Apex=a,RidgeDirection=((ComboBox)Inputs["RidgeDirection"]).SelectedIndex};try{b.Validate();value=b;return true;}catch{return false;}}
 double ExposureHeight(){WindBuildingInput b;return TryBuildingGeometry(out b)?b.Height:double.NaN;}
 void AddBuildingModel(FlowLayoutPanel panel){var page=(TabPage)panel.Parent;page.Controls.Remove(panel);var split=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2,RowCount=1};split.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,55));split.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,45));split.RowStyles.Add(new RowStyle(SizeType.Percent,100));panel.Dock=DockStyle.Fill;buildingModel=new WindBuildingModel{Dock=DockStyle.Fill,Margin=new Padding(10)};split.Controls.Add(panel,0,0);split.Controls.Add(buildingModel,1,0);page.Controls.Add(split);foreach(string key in new[]{"BuildingWidth","BuildingLength","Eave","Apex","RidgeDirection"}){string captured=key;Inputs[key].Enter+=(s,e)=>{buildingModel.Highlight=captured;buildingModel.Invalidate();};Inputs[key].TextChanged+=(s,e)=>{buildingModel.Highlight=captured;RefreshBuildingModel();};}buildingRefresh.Tick+=(s,e)=>{buildingRefresh.Stop();UpdateResults();};FormClosed+=(s,e)=>buildingRefresh.Dispose();RefreshBuildingModel();}
 void RefreshBuildingModel(){if(buildingModel==null)return;WindBuildingInput b;buildingModel.Geometry=TryBuildingGeometry(out b)?b:null;buildingModel.Invalidate();if(!Restoring){buildingRefresh.Stop();buildingRefresh.Start();}}
}
class WindBuildingModel:Control {
 public WindBuildingInput Geometry;public string Highlight;double yaw=-.65,tilt=.5,zoom=1;Point drag;bool rotating;
 struct V {public double X,Y,Z;public V(double x,double y,double z){X=x;Y=y;Z=z;}}
 public WindBuildingModel(){DoubleBuffered=true;ResizeRedraw=true;MinimumSize=new Size(300,320);MouseDown+=(s,e)=>{rotating=true;drag=e.Location;Capture=true;};MouseMove+=(s,e)=>{if(!rotating)return;yaw+=(e.X-drag.X)*.012;tilt=Math.Max(.2,Math.Min(1.15,tilt+(e.Y-drag.Y)*.007));drag=e.Location;Invalidate();};MouseUp+=(s,e)=>{rotating=false;Capture=false;};MouseWheel+=(s,e)=>{zoom=Math.Max(.5,Math.Min(2.5,zoom*(e.Delta>0?1.1:1/1.1)));Invalidate();};DoubleClick+=(s,e)=>{yaw=-.65;tilt=.5;zoom=1;Invalidate();};}
 protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);var g=e.Graphics;g.Clear(ModernUi.Surface);g.SmoothingMode=SmoothingMode.AntiAlias;TextRenderer.DrawText(g,"Building geometry",PremiumControls.TitleFont,new Point(18,15),PowTheme.Ink);TextRenderer.DrawText(g,"Drag to rotate · scroll to zoom · double-click to reset",ModernUi.Body,new Rectangle(18,52,Width-36,42),PowTheme.Muted);var b=Geometry;if(b==null){TextRenderer.DrawText(g,"Enter valid width, length, eave and apex heights.",ModernUi.Body,new Rectangle(25,Height/2-30,Width-50,70),PowTheme.Muted,TextFormatFlags.WordBreak);return;}double w=b.Width/2,l=b.Length/2;V[] p={new V(-w,-l,0),new V(w,-l,0),new V(w,l,0),new V(-w,l,0),new V(-w,-l,b.Eave),new V(w,-l,b.Eave),new V(w,l,b.Eave),new V(-w,l,b.Eave),new V(0,-l,b.Apex),new V(0,l,b.Apex)};Func<V,PointF> raw=v=>new PointF((float)(v.X*Math.Cos(yaw)-v.Y*Math.Sin(yaw)),(float)((v.X*Math.Sin(yaw)+v.Y*Math.Cos(yaw))*Math.Sin(tilt)-v.Z*Math.Cos(tilt)));var r=p.Select(raw).ToArray();double minx=r.Min(v=>v.X),maxx=r.Max(v=>v.X),miny=r.Min(v=>v.Y),maxy=r.Max(v=>v.Y),scale=Math.Min((Width-100)/Math.Max(.1,maxx-minx),(Height-210)/Math.Max(.1,maxy-miny))*zoom;Func<V,PointF> project=v=>{var q=raw(v);return new PointF((float)(Width/2+(q.X-(minx+maxx)/2)*scale),(float)(Height/2+25+(q.Y-(miny+maxy)/2)*scale));};var pts=p.Select(project).ToArray();int[][] faces={new[]{0,1,5,8,4},new[]{1,2,6,5},new[]{2,3,7,9,6},new[]{3,0,4,7},new[]{4,8,9,7},new[]{8,5,6,9}};for(int i=0;i<faces.Length;i++){using(var fill=new SolidBrush(i>=4?DesktopAppearance.Palette.Selected:ModernUi.Soft))g.FillPolygon(fill,faces[i].Select(n=>pts[n]).ToArray());using(var pen=new Pen(PowTheme.Line,1.2f))g.DrawPolygon(pen,faces[i].Select(n=>pts[n]).ToArray());}
  Dimension(g,pts[0],pts[1],"W = "+b.Width.ToString("0.##")+" m",Highlight=="BuildingWidth",0,24);Dimension(g,pts[1],pts[2],"L = "+b.Length.ToString("0.##")+" m",Highlight=="BuildingLength",25,15);Dimension(g,pts[1],pts[5],"Eave "+b.Eave.ToString("0.##")+" m",Highlight=="Eave",30,0);Dimension(g,pts[0],pts[8],"Apex "+b.Apex.ToString("0.##")+" m",Highlight=="Apex",-35,-14);
  TextRenderer.DrawText(g,"Mean roof h = "+b.Height.ToString("0.##")+" m  |  Roof slope = "+b.Angle.ToString("0.##")+"°",ModernUi.Strong,new Rectangle(18,Height-74,Width-36,30),PowTheme.Ink,TextFormatFlags.WordBreak);TextRenderer.DrawText(g,"Ridge "+new[]{"N–S","NE–SW","E–W","NW–SE"}[b.RidgeDirection]+" · h uses eave height when slope ≤10°",ModernUi.Body,new Rectangle(18,Height-40,Width-36,36),PowTheme.Muted,TextFormatFlags.WordBreak);
 }
 static void Dimension(Graphics g,PointF a,PointF b,string label,bool active,float dx,float dy){a=new PointF(a.X+dx,a.Y+dy);b=new PointF(b.X+dx,b.Y+dy);Color color=active?PowTheme.Teal:PowTheme.Muted;using(var pen=new Pen(color,active?2:1){StartCap=LineCap.DiamondAnchor,EndCap=LineCap.DiamondAnchor})g.DrawLine(pen,a,b);var midpoint=new Point((int)((a.X+b.X)/2)-65,(int)((a.Y+b.Y)/2)-20);TextRenderer.DrawText(g,label,ModernUi.Body,new Rectangle(midpoint,new Size(150,40)),color,ModernUi.Surface,TextFormatFlags.WordBreak);}
}
}
